section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/hipaa-phi-data-flow-design.json",
  "title": "HIPAA PHI data-flow design",
  "type": "object",
  "required": ["system", "hops", "links", "audit_log", "log_scrubbing", "deletion_propagation", "media_disposal_procedure", "review"],
  "additionalProperties": false,
  "definitions": {
    "identifier_class": {
      "type": "string",
      "enum": ["names", "geographic_subdivisions_smaller_than_state", "dates_except_year", "phone_numbers", "fax_numbers", "email_addresses", "social_security_numbers", "medical_record_numbers", "health_plan_beneficiary_numbers", "account_numbers", "certificate_license_numbers", "vehicle_identifiers", "device_identifiers", "web_urls", "ip_addresses", "biometric_identifiers", "full_face_photos", "other_unique_identifying_number"]
    }
  },
  "properties": {
    "system": {"type": "string", "minLength": 3},
    "hops": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["id", "name", "kind", "operations", "external", "identifier_classes", "fields", "purpose", "deidentified", "access", "retention"],
        "properties": {
          "id": {"type": "string", "pattern": "^hop-[a-z0-9-]+$"},
          "name": {"type": "string", "minLength": 2},
          "kind": {"type": "string", "enum": ["service", "database", "queue", "cache", "search_index", "log_pipeline", "error_tracker", "analytics", "machine_learning", "llm_or_embeddings_api", "email_or_sms_gateway", "support_desk", "backup", "export", "object_storage", "third_party_api", "other"]},
          "operations": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string", "enum": ["stores", "processes", "transmits"]}},
          "external": {"type": "boolean"},
          "identifier_classes": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/definitions/identifier_class"}},
          "fields": {
            "type": "array",
            "items": {
              "type": "object",
              "required": ["name", "justification"],
              "properties": {
                "name": {"type": "string", "minLength": 1},
                "justification": {"type": "string", "minLength": 10}
              }
            }
          },
          "purpose": {"type": "string", "minLength": 10},
          "deidentified": {"type": "boolean"},
          "deidentification_method": {"type": "string", "enum": ["safe_harbor_164_514_b_2", "expert_determination_164_514_b_1"]},
          "identified_use_documented_at": {"type": "string", "minLength": 3},
          "baa": {
            "type": "object",
            "required": ["executed", "vendor", "plan", "covered_service", "link"],
            "properties": {
              "executed": {"const": true},
              "vendor": {"type": "string", "minLength": 2},
              "plan": {"type": "string", "minLength": 2},
              "covered_service": {"type": "string", "minLength": 2},
              "link": {"type": "string", "minLength": 3},
              "executed_on": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"}
            }
          },
          "encryption_at_rest": {
            "type": "object",
            "required": ["enabled", "kms", "key_rotation_enabled"],
            "properties": {
              "enabled": {"const": true},
              "standard": {"type": "string"},
              "kms": {"type": "string", "minLength": 3},
              "key_rotation_enabled": {"const": true}
            }
          },
          "access": {
            "type": "object",
            "required": ["roles", "shared_accounts", "auto_logoff_minutes", "break_glass"],
            "properties": {
              "roles": {
                "type": "array",
                "minItems": 1,
                "items": {
                  "type": "object",
                  "required": ["role", "operations"],
                  "properties": {
                    "role": {"type": "string", "minLength": 2},
                    "operations": {"type": "array", "minItems": 1, "items": {"type": "string", "enum": ["read", "write", "export", "delete", "admin"]}}
                  }
                }
              },
              "shared_accounts": {"const": false},
              "auto_logoff_minutes": {"type": "integer", "minimum": 1},
              "break_glass": {
                "type": "object",
                "required": ["documented_at", "audit_alert"],
                "properties": {
                  "documented_at": {"type": "string", "minLength": 3},
                  "audit_alert": {"type": "string", "minLength": 3}
                }
              }
            }
          },
          "retention": {
            "type": "object",
            "required": ["period_days", "deletion_mechanism"],
            "properties": {
              "period_days": {"type": "integer", "minimum": 0},
              "deletion_mechanism": {"type": "string", "minLength": 5}
            }
          }
        },
        "allOf": [
          {"if": {"properties": {"operations": {"contains": {"const": "stores"}}}}, "then": {"required": ["encryption_at_rest"]}},
          {"if": {"properties": {"deidentified": {"const": true}}}, "then": {"required": ["deidentification_method"]}},
          {"if": {"properties": {"external": {"const": true}, "deidentified": {"const": false}}}, "then": {"required": ["baa"]}},
          {"if": {"properties": {"kind": {"enum": ["analytics", "machine_learning", "llm_or_embeddings_api"]}, "deidentified": {"const": false}}}, "then": {"required": ["baa", "identified_use_documented_at"]}},
          {"if": {"properties": {"deidentified": {"const": false}}}, "then": {"properties": {"identifier_classes": {"minItems": 1}, "fields": {"minItems": 1}}}}
        ]
      }
    },
    "links": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["from", "to", "tls_version", "tls_terminates_at", "identifier_classes"],
        "properties": {
          "from": {"type": "string", "pattern": "^hop-[a-z0-9-]+$"},
          "to": {"type": "string", "pattern": "^hop-[a-z0-9-]+$"},
          "tls_version": {"type": "string", "enum": ["1.2", "1.3"]},
          "tls_terminates_at": {"type": "string", "minLength": 2},
          "identifier_classes": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/definitions/identifier_class"}}
        }
      }
    },
    "audit_log": {
      "type": "object",
      "required": ["store", "append_only", "contains_phi_field_values", "retention_years", "event_fields", "bulk_access_alert"],
      "properties": {
        "store": {"type": "string", "minLength": 3},
        "append_only": {"const": true},
        "contains_phi_field_values": {"const": false},
        "retention_years": {"type": "integer", "minimum": 6},
        "event_fields": {
          "type": "array",
          "uniqueItems": true,
          "allOf": [
            {"contains": {"const": "identity"}},
            {"contains": {"const": "timestamp"}},
            {"contains": {"const": "record_id"}},
            {"contains": {"const": "action"}},
            {"contains": {"const": "originating_system"}}
          ],
          "items": {"type": "string"}
        },
        "bulk_access_alert": {"type": "string", "minLength": 3}
      }
    },
    "log_scrubbing": {
      "type": "object",
      "required": ["allow_list_scrubber_at", "phi_in_urls_or_query_strings", "synthetic_record_test"],
      "properties": {
        "allow_list_scrubber_at": {"type": "string", "minLength": 3},
        "phi_in_urls_or_query_strings": {"const": false},
        "synthetic_record_test": {
          "type": "object",
          "required": ["path", "covers_every_request_path", "asserts_no_identifier_in_logs_errors_traces", "runs_in_ci"],
          "properties": {
            "path": {"type": "string", "minLength": 3},
            "covers_every_request_path": {"const": true},
            "asserts_no_identifier_in_logs_errors_traces": {"const": true},
            "runs_in_ci": {"const": true}
          }
        }
      }
    },
    "deletion_propagation": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["trigger", "propagates_to", "mechanism"],
        "properties": {
          "trigger": {"type": "string", "minLength": 5},
          "propagates_to": {"type": "array", "minItems": 1, "items": {"type": "string", "pattern": "^hop-[a-z0-9-]+$"}},
          "mechanism": {"type": "string", "minLength": 5}
        }
      }
    },
    "media_disposal_procedure": {"type": "string", "minLength": 5},
    "review": {
      "type": "object",
      "required": ["status", "approved_by_agent"],
      "properties": {
        "status": {"type": "string", "enum": ["draft", "ready_for_review", "approved"]},
        "security_officer": {"type": "string", "minLength": 3},
        "signed_on": {"type": "string", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
        "approved_by_agent": {"const": false}
      },
      "if": {"properties": {"status": {"const": "approved"}}},
      "then": {"required": ["security_officer", "signed_on"]}
    }
  }
}
